#include "GuildContractsModel.h"
#include <cassert>
#include <iostream>
int main(){using namespace GuildContracts;std::vector<Row> rows;assert(pages(0,10)==1&&filter(rows,-1,"",false).empty());for(int i=0;i<103;++i){Row r;r.status=i%3;r.name=i%2?"Heng":"Squin";r.donor="Police";r.key=std::string(i+1,'x');rows.push_back(r);}Counts c=count(rows);assert(c.total==103&&c.active==35&&c.completed==34&&c.failed==34);assert(pages(103,10)==11&&clampPage(100,103,10)==10);std::vector<int> all=filter(rows,-1,"",false),reverse=filter(rows,-1,"",true);assert(all.size()==103&&reverse[0]==101);assert(filter(rows,-1,"none",false).empty());std::vector<int> active=filter(rows,Active,"hEnG",false);for(size_t i=0;i<active.size();++i)assert(rows[active[i]].status==Active&&rows[active[i]].name=="Heng");assert(filter(rows,-1,"POLICE",false).size()==103);assert(find(rows,rows[54].key)==54);assert(find(rows,"missing")==-1);std::cout<<"PASS: counts, 0/1/103 rows, all statuses, combined search/filter, sort, pagination, stable selection.\n";}
